/// `constructor(TouchInit touchInitDict);`
fn ctor_0<'s, D: Dom, const LO: u16, const HI: u16>(
    scope: &mut v8::PinScope<'s, '_>,
    args: &v8::FunctionCallbackArguments,
    argc: i32,
) -> Option<Handle> {
    let a0 = {
        let v = args.get(0);
        TouchInit::from_js(scope, v)
    }?;
    let st = rt::state(scope);
    let dom = st.engine::<D>();

    let r = {
        let mut cx = Cx::new(scope);
        <D as TouchImpl>::constructor(dom, &mut cx, a0)
    };

    let v = rt::check(scope, r)?;
    Some(v)
}

/// Overload resolution of `Touch.constructor` (Web IDL §3.7.6).
fn ctor_dispatch<'s, D: Dom, const LO: u16, const HI: u16>(
    scope: &mut v8::PinScope<'s, '_>,
    args: &v8::FunctionCallbackArguments,
) -> Option<Handle> {
    let argc = args.length();
    if argc < 1 {
        return rt::not_enough_arguments(scope, "Touch.constructor", 1, argc);
    }
    ctor_0::<D, LO, HI>(scope, args, argc)
}

/// The `Touch` constructor.
fn ctor_callback<D: Dom>(
    scope: &mut v8::PinScope,
    args: v8::FunctionCallbackArguments,
    mut rv: v8::ReturnValue,
) {
    let _prof = rt::prof::enter(scope, "new Touch");
    const LO: u16 = ids::TOUCH;
    const HI: u16 = ids::TOUCH_END;
    if !args.is_construct_call() {
        return rt::throw_type_error(
            scope,
            "Failed to construct 'Touch': Please use the 'new' operator",
        );
    }
    let Some(h) = ctor_dispatch::<D, LO, HI>(scope, &args) else {
        return;
    };
    rt::adopt_wrapper(scope, args.this(), h, LO);
    rv.set(args.this().into());
}

